import { useState } from 'react';
import { Button, Card, Input, Stack, Stepper, Step, Text } from '@jinx-ui/react';

type RegistrationData = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationWizardProps = {
  onSubmit: (data: RegistrationData) => void;
};

const STEPS = ['Контакты', 'Адрес', 'Проверка'];

const EMPTY: RegistrationData = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(EMPTY);

  const update = (field: keyof RegistrationData) => (value: string) =>
    setData((prev) => ({ ...prev, [field]: value }));

  const isLast = step === STEPS.length - 1;

  return (
    <Card>
      <Stack direction="vertical" style={{ gap: 'var(--jx-space-6)' }}>
        <Stepper activeStep={step}>
          {STEPS.map((label) => (
            <Step key={label} label={label} />
          ))}
        </Stepper>

        {step === 0 && (
          <Stack direction="vertical" style={{ gap: 'var(--jx-space-4)' }}>
            <Input label="Имя" value={data.name} onChange={update('name')} />
            <Input label="Email" type="email" value={data.email} onChange={update('email')} />
            <Input label="Телефон" type="tel" value={data.phone} onChange={update('phone')} />
          </Stack>
        )}

        {step === 1 && (
          <Stack direction="vertical" style={{ gap: 'var(--jx-space-4)' }}>
            <Input label="Страна" value={data.country} onChange={update('country')} />
            <Input label="Город" value={data.city} onChange={update('city')} />
            <Input label="Улица, дом" value={data.street} onChange={update('street')} />
            <Input label="Индекс" value={data.zip} onChange={update('zip')} />
          </Stack>
        )}

        {step === 2 && (
          <Stack direction="vertical" style={{ gap: 'var(--jx-space-3)' }}>
            <Text weight="bold">Проверьте данные</Text>
            <Text>Имя: {data.name}</Text>
            <Text>Email: {data.email}</Text>
            <Text>Телефон: {data.phone}</Text>
            <Text>Страна: {data.country}</Text>
            <Text>Город: {data.city}</Text>
            <Text>Улица, дом: {data.street}</Text>
            <Text>Индекс: {data.zip}</Text>
          </Stack>
        )}

        <Stack direction="horizontal" style={{ gap: 'var(--jx-space-3)' }}>
          <Button variant="secondary" disabled={step === 0} onClick={() => setStep((s) => s - 1)}>
            Назад
          </Button>
          {isLast ? (
            <Button variant="primary" onClick={() => onSubmit(data)}>
              Отправить
            </Button>
          ) : (
            <Button variant="primary" onClick={() => setStep((s) => s + 1)}>
              Дальше
            </Button>
          )}
        </Stack>
      </Stack>
    </Card>
  );
}

